export type Campo =
  | { nome: string; rotulo: string; tipo: 'texto' | 'area' | 'numero' | 'data'; padrao?: string; ajuda?: string }
  | { nome: string; rotulo: string; tipo: 'selecao'; opcoes: [string, string][]; padrao?: string; ajuda?: string }
  | { nome: string; rotulo: string; tipo: 'marcar'; opcoes: [string, string][]; padrao?: string[]; ajuda?: string }
  | { nome: string; rotulo: string; tipo: 'sim'; padrao?: boolean; ajuda?: string }
export type Valores = Record<string, string | string[] | boolean>
export type Resultado = { linhas: [string, string][]; texto?: string; alertas?: string[] }
export type Categoria = 'Prazos e datas' | 'Cálculos' | 'Locação (Lei 8.245/91)' | 'Validação de documentos' | 'Redação e linguagem' | 'Modelos prontos' | 'Listas de verificação' | 'Gestão e bem-estar' | 'Estudos para entidades'
export type Ferramenta = { id: string; nome: string; categoria: Categoria; descricao: string; base?: string; campos: Campo[]; executar: (v: Valores) => Resultado }

/** "hoje" nos padrões de data vira a data local do dia. */
export const HOJE = 'hoje'
export function hojeIso(agora = new Date()): string { const d = new Date(agora.getTime() - agora.getTimezoneOffset() * 60000); return d.toISOString().slice(0, 10) }
export function valoresPadrao(f: Ferramenta, agora = new Date()): Valores {
  const v: Valores = {}
  for (const c of f.campos) {
    if (c.tipo === 'marcar') v[c.nome] = c.padrao ?? []
    else if (c.tipo === 'sim') v[c.nome] = c.padrao ?? false
    else v[c.nome] = c.padrao === HOJE ? hojeIso(agora) : (c.padrao ?? (c.tipo === 'selecao' ? c.opcoes[0][0] : ''))
  }
  return v
}

const s = (v: Valores, k: string) => String(v[k] ?? '').trim()
const n = (v: Valores, k: string, padrao = 0) => { const x = num(v[k]); return Number.isFinite(x) ? x : padrao }
const arr = (v: Valores, k: string) => (Array.isArray(v[k]) ? (v[k] as string[]) : [])
const b = (v: Valores, k: string) => v[k] === true || v[k] === 'true'
function d(v: Valores, k: string, rotulo: string): string {
  const x = s(v, k)
  if (!dataValida(x)) throw new Error(`Informe uma data válida em "${rotulo}".`)
  return x
}
const dt = (x: string) => `${br(x)} (${diaDaSemana(x)})`
const txt = (v: Valores, k: string, rotulo: string) => { const x = s(v, k); if (!x) throw new Error(`Preencha "${rotulo}".`); return x }
const pos = (x: number, rotulo: string) => { if (!(x > 0)) throw new Error(`Informe um valor maior que zero em "${rotulo}".`); return x }

