export const CATEGORIAS: Categoria[] = ['Prazos e datas', 'Cálculos', 'Locação (Lei 8.245/91)', 'Validação de documentos', 'Redação e linguagem', 'Modelos prontos', 'Listas de verificação', 'Gestão e bem-estar', 'Estudos para entidades']

/** Executa a ferramenta e transforma erros de entrada em mensagem para a pessoa. */
export function rodar(f: Ferramenta, v: Valores): { ok: true; resultado: Resultado } | { ok: false; erro: string } {
  try { return { ok: true, resultado: f.executar(v) } } catch (e) { return { ok: false, erro: e instanceof Error ? e.message : 'Não foi possível calcular.' } }
}
export function buscarFerramentas(termo: string, lista = FERRAMENTAS): Ferramenta[] {
  const t = termo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim()
  if (!t) return lista
  return lista.filter(f => `${f.nome} ${f.descricao} ${f.categoria} ${f.base ?? ''}`.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').includes(t))
}
